/** URL 是否来自苏服办跳转（token + 身份参数缺一不可） */
export const isSfbLoginEntry = () => {
  return isSfbLikeUrl() && getSfbMissingFieldLabels().length === 0
}

const SFB_TOKEN_STORAGE_KEY = 'sfb_sdk_token'

const maskMiddle = (value, headLen, tailLen) => {
  const text = `${value || ''}`
  if (!text) return '(空)'
  if (headLen + tailLen <= 0) return '***'
  if (text.length <= headLen + tailLen) return '***'
  return `${text.slice(0, headLen)}***${text.slice(-tailLen)}`
}

/** 苏服办身份密文脱敏：姓名只留首字，手机/证件前 3 后 4 */
const maskSfbIdentity = (key, value) => {
  if (!value) return '(空)'
  if (key === 'name') return maskMiddle(value, 1, 0)
  if (key === 'phone') return maskMiddle(value, 3, 4)
  if (key === 'idNumber') return maskMiddle(value, 3, 4)
  return '***'
}

/** 本链路关注的 URL 参数（均在 h5Context 内实际读取） */
const SFB_JUMP_LOG_KEYS = [
  'token',
  'name',
  'idType',
  'idNumber',
  'phone',
  'topicvoteid',
  'complexId',
  'houseId',
]

/**
 * 苏服办跳转链路日志：记录入口 URL、参数存在性与脱敏后的密文值，供协调三方排查跳转问题。
 * 纯日志，无副作用；密文按字段差异化脱敏，不输出完整身份信息。
 */
export const logSfbJumpContext = (source = 'unknown') => {
  /* #ifdef H5 */
  try {
    const rawUrl = `${window.location.href || ''}`
    const masked = {}
    const presence = {}

    SFB_JUMP_LOG_KEYS.forEach((key) => {
      const raw = getH5Param(key)
      presence[key] = !!raw
      if (!raw) return
      masked[key] = key === 'token' ? maskMiddle(raw, 4, 4) : maskSfbIdentity(key, raw)
    })

    const ua = `${navigator.userAgent || ''}`
    cacheLog(`[苏服办跳转] ${source}`, {
      href: rawUrl.split('?')[0],
      hash: `${window.location.hash || ''}`.split('?')[0],
      searchLength: `${window.location.search || ''}`.length,
      hashLength: `${window.location.hash || ''}`.length,
      paramPresence: presence,
      maskedParams: masked,
      missingFields: getSfbMissingFieldLabels(),
      sfbLike: isSfbLikeUrl(),
      sfbLoginEntry: isSfbLoginEntry(),
      referrer: document.referrer || '(空)',
      isAlipay: /AlipayClient|AliApp/i.test(ua),
      isHanweb: /hanweb/i.test(ua) && !/dtdreamweb/i.test(ua),
    })
  } catch (error) {
    console.warn('[苏服办跳转] 日志采集失败', error)
  }
  /* #endif */
}

