tool_input.command:
node --input-type=module -e "
const LABELS={token:'token',name:'姓名',idType:'证件类型',idNumber:'证件号码',phone:'手机号'};
const KEYS=['token','name','idType','idNumber','phone'];
const HINT='缺少手机号，请至苏服办-个人信息绑定手机号';
const get=(params,k)=>params[k]||'';
const missingOf=(params)=>KEYS.filter(k=>!get(params,k)).map(k=>LABELS[k]);
const hintOf=(params)=>{const m=missingOf(params); if(!m.length) return null; const onlyPhone=m.length===1&&m[0]===LABELS.phone; return onlyPhone?HINT:'缺少'+m.join('、');};
const cases={
 '仅缺phone':{token:'t',name:'n',idType:'1',idNumber:'i'},
 '全部齐全':{token:'t',name:'n',idType:'1',idNumber:'i',phone:'p'},
 '缺token+name':{idType:'1',idNumber:'i',phone:'p'},
 '缺phone+idNumber':{token:'t',name:'n',idType:'1'}
};
for(const [k,v] of Object.entries(cases)) console.log(k,'=>',hintOf(v));
"
